document.addEventListener("DOMContentLoaded",function(){const apiUrl="https://pokeapi.co/api/v2/pokemon/?limit=150";const pokemonList=document.getElementById("pokemonList");const modal=document.getElementById("modal");const modalTitle=document.getElementById("modalTitle");const modalImage=document.getElementById("modalImage");const modalHeight=document.getElementById("modalHeight");const modalAbilities=document.getElementById("modalAbilities");const closeButton=document.getElementById("closeButton");const searchInput=document.getElementById("searchInput");fetch(apiUrl).then(response=>response.json()).then(data=>{data.results.forEach((pokemon,index)=>{const pokemonNumber=`#`+(index+1).toString().padStart(3,"0");const card=document.createElement("div");card.classList.add("card","col-md-2","custom-card");card.style.width="100%";card.style.marginBottom="20px";card.style.backgroundColor="white";card.style.boxShadow="0 4px 8px 0 rgba(0, 0, 0, 0.2)";card.style.transition="transform 0.2s";card.style.cursor="pointer";card.style.textAlign="center";card.style.display="flex";card.style.flexDirection="column";card.style.justifyContent="center";card.style.borderRadius="5px";card.style.margin="10px";card.innerHTML=`
          <img src="https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${index+1}.png" alt="${pokemon.name}" class="card-img-top">
          <div class="card-body">
            <h5 class="card-title text-capitalize text-center">${pokemon.name}</h5>
            <p class="card-text">${pokemonNumber}</p> <!-- Display Pokémon number -->
          </div>
        `;card.addEventListener("click",async()=>{modalTitle.textContent=pokemon.name.charAt(0).toUpperCase()+pokemon.name.slice(1);modalTitle.classList.add("text-center");modalImage.src=`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${index+1}.png`;modalImage.style.width="300px";const heightResponse=await fetch(`https://pokeapi.co/api/v2/pokemon/${index+1}`);const heightData=await heightResponse.json();modalHeight.textContent=`Height: ${heightData.height*10} cm`;const pokemonDetailsResponse=await fetch(`https://pokeapi.co/api/v2/pokemon/${index+1}`);const pokemonDetails=await pokemonDetailsResponse.json();const abilities=pokemonDetails.abilities.map(ability=>ability.ability.name.charAt(0).toUpperCase()+ability.ability.name.slice(1));modalAbilities.innerHTML="<strong>Abilities:</strong> "+abilities.join(", ");modal.style.display="block"});pokemonList.appendChild(card)})});searchInput.addEventListener("keyup",function(){const searchValue=searchInput.value.toLowerCase();const pokemonCards=document.querySelectorAll(".card");pokemonCards.forEach(card=>{const pokemonName=card.querySelector(".card-title").textContent.toLowerCase();if(pokemonName.includes(searchValue)){card.style.display="block"}else{card.style.display="none"}})});closeButton.addEventListener("click",()=>{modal.style.display="none"});window.addEventListener("click",event=>{if(event.target===modal){modal.style.display="none"}});window.addEventListener("keydown",event=>{if(event.key==="Escape"){modal.style.display="none"}});const backButton=document.getElementById("back-to-top");window.addEventListener("scroll",()=>{if(window.scrollY>0){backButton.style.display="block"}else{backButton.style.display="none"}});backButton.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})})});